import{_ as d,c as e,o as r,a2 as o}from"./chunks/framework.D30IVGRC.js";const u=JSON.parse('{"title":"ESLint 插件规则说明","description":"eslint-plugin-smart 提供的规则详细说明","frontmatter":{"title":"ESLint 插件规则说明","description":"eslint-plugin-smart 提供的规则详细说明","outline":"deep"},"headers":[],"relativePath":"lint/eslint-plugin-smart/docs/规则说明.md","filePath":"lint/eslint-plugin-smart/docs/规则说明.md","lastUpdated":1745226716000}'),a={name:"lint/eslint-plugin-smart/docs/规则说明.md"};function c(n,t,s,i,l,p){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="规则说明" tabindex="-1">规则说明 <a class="header-anchor" href="#规则说明" aria-label="Permalink to &quot;规则说明&quot;">​</a></h1><p>本文档详细介绍了 eslint-plugin-smart 中包含的规则及其分类。根据项目类型，这些规则被组织成多个预设配置，以便您根据需要进行选择。</p><h2 id="预设配置" tabindex="-1">预设配置 <a class="header-anchor" href="#预设配置" aria-label="Permalink to &quot;预设配置&quot;">​</a></h2><p>eslint-plugin-smart 提供了以下几种预设配置：</p><table tabindex="0"><thead><tr><th>预设配置</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><code>smart/recommended</code></td><td>基础推荐配置</td><td>适用于所有 JavaScript 项目</td></tr><tr><td><code>smart/typescript</code></td><td>TypeScript 配置</td><td>适用于 TypeScript 项目</td></tr><tr><td><code>smart/react</code></td><td>React 配置</td><td>适用于 React 项目</td></tr><tr><td><code>smart/vue</code></td><td>Vue 配置</td><td>适用于 Vue 项目</td></tr><tr><td><code>smart/nestjs</code></td><td>NestJS 配置</td><td>适用于 NestJS 后端项目</td></tr></tbody></table><h2 id="基础规则" tabindex="-1">基础规则 <a class="header-anchor" href="#基础规则" aria-label="Permalink to &quot;基础规则&quot;">​</a></h2><p>以下是 <code>smart/recommended</code> 配置中包含的基础规则：</p><h3 id="代码风格规则" tabindex="-1">代码风格规则 <a class="header-anchor" href="#代码风格规则" aria-label="Permalink to &quot;代码风格规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>indent</code></td><td>使用一致的缩进（默认为2空格）</td><td>错误</td></tr><tr><td><code>quotes</code></td><td>使用一致的引号风格（默认为单引号）</td><td>错误</td></tr><tr><td><code>semi</code></td><td>要求或禁止使用分号</td><td>错误</td></tr><tr><td><code>no-unused-vars</code></td><td>禁止出现未使用过的变量</td><td>警告</td></tr><tr><td><code>comma-dangle</code></td><td>要求或禁止末尾逗号</td><td>警告</td></tr><tr><td><code>arrow-parens</code></td><td>箭头函数参数括号风格</td><td>警告</td></tr><tr><td><code>max-len</code></td><td>强制行的最大长度</td><td>警告</td></tr><tr><td><code>eol-last</code></td><td>要求或禁止文件末尾保留一行空行</td><td>错误</td></tr></tbody></table><h3 id="代码质量规则" tabindex="-1">代码质量规则 <a class="header-anchor" href="#代码质量规则" aria-label="Permalink to &quot;代码质量规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>no-console</code></td><td>禁用 console 方法</td><td>警告</td></tr><tr><td><code>no-debugger</code></td><td>禁用 debugger</td><td>错误</td></tr><tr><td><code>no-alert</code></td><td>禁用 alert、confirm 和 prompt</td><td>错误</td></tr><tr><td><code>no-eval</code></td><td>禁用 eval()</td><td>错误</td></tr><tr><td><code>no-implied-eval</code></td><td>禁止使用类似 eval() 的方法</td><td>错误</td></tr><tr><td><code>no-new-func</code></td><td>禁止对 Function 对象使用 new 操作符</td><td>错误</td></tr><tr><td><code>no-return-assign</code></td><td>禁止在 return 语句中使用赋值语句</td><td>错误</td></tr><tr><td><code>no-prototype-builtins</code></td><td>禁止直接使用 Object.prototypes 的内置属性</td><td>错误</td></tr><tr><td><code>curly</code></td><td>强制所有控制语句使用一致的括号风格</td><td>错误</td></tr></tbody></table><h3 id="导入-导出规则" tabindex="-1">导入/导出规则 <a class="header-anchor" href="#导入-导出规则" aria-label="Permalink to &quot;导入/导出规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>import/order</code></td><td>强制导入的排序</td><td>警告</td></tr><tr><td><code>import/first</code></td><td>确保所有导入都在文件顶部</td><td>错误</td></tr><tr><td><code>import/no-mutable-exports</code></td><td>禁止导出可变的绑定</td><td>错误</td></tr><tr><td><code>import/no-unresolved</code></td><td>确保导入的模块可以被解析</td><td>错误</td></tr><tr><td><code>import/no-webpack-loader-syntax</code></td><td>禁止在导入中使用 Webpack 加载器语法</td><td>错误</td></tr></tbody></table><h2 id="typescript-规则" tabindex="-1">TypeScript 规则 <a class="header-anchor" href="#typescript-规则" aria-label="Permalink to &quot;TypeScript 规则&quot;">​</a></h2><p><code>smart/typescript</code> 配置在基础规则基础上增加了对 TypeScript 的支持：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>@typescript-eslint/explicit-function-return-type</code></td><td>要求函数和类方法的显式返回类型</td><td>警告</td></tr><tr><td><code>@typescript-eslint/explicit-module-boundary-types</code></td><td>要求导出函数和类方法的显式返回和参数类型</td><td>警告</td></tr><tr><td><code>@typescript-eslint/ban-ts-comment</code></td><td>禁止特定类型的注释或要求注释包含描述</td><td>警告</td></tr><tr><td><code>@typescript-eslint/no-explicit-any</code></td><td>禁止使用 any 类型</td><td>警告</td></tr><tr><td><code>@typescript-eslint/no-unused-vars</code></td><td>禁止定义未使用的变量</td><td>错误</td></tr><tr><td><code>@typescript-eslint/no-non-null-assertion</code></td><td>禁止使用非空断言</td><td>警告</td></tr><tr><td><code>@typescript-eslint/type-annotation-spacing</code></td><td>要求类型注释周围的一致空格</td><td>错误</td></tr><tr><td><code>@typescript-eslint/member-delimiter-style</code></td><td>要求或禁止在接口和类型字面量中使用分号</td><td>错误</td></tr></tbody></table><h2 id="react-规则" tabindex="-1">React 规则 <a class="header-anchor" href="#react-规则" aria-label="Permalink to &quot;React 规则&quot;">​</a></h2><p><code>smart/react</code> 配置针对 React 项目，包含以下特定规则：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>react/jsx-uses-react</code></td><td>防止 React 被标记为未使用</td><td>错误</td></tr><tr><td><code>react/jsx-uses-vars</code></td><td>防止 JSX 中使用的变量被标记为未使用</td><td>错误</td></tr><tr><td><code>react/prop-types</code></td><td>验证 props 对象类型的定义</td><td>警告</td></tr><tr><td><code>react/react-in-jsx-scope</code></td><td>使用 JSX 时防止丢失 React</td><td>错误</td></tr><tr><td><code>react/jsx-pascal-case</code></td><td>强制使用 PascalCase 作为 JSX 组件名</td><td>错误</td></tr><tr><td><code>react/jsx-key</code></td><td>防止在数组或迭代器中使用的 JSX 缺少 key 属性</td><td>错误</td></tr><tr><td><code>react/jsx-no-duplicate-props</code></td><td>防止 JSX 中出现重复的 props</td><td>错误</td></tr><tr><td><code>react/jsx-curly-brace-presence</code></td><td>强制使用花括号或不使用花括号</td><td>警告</td></tr><tr><td><code>react/jsx-boolean-value</code></td><td>在 JSX 中强制布尔属性符号</td><td>警告</td></tr><tr><td><code>react/no-array-index-key</code></td><td>防止在数组索引处使用 key</td><td>警告</td></tr><tr><td><code>react/no-direct-mutation-state</code></td><td>防止直接修改 this.state</td><td>错误</td></tr><tr><td><code>react/no-unsafe</code></td><td>防止使用不安全的生命周期方法</td><td>错误</td></tr><tr><td><code>react-hooks/rules-of-hooks</code></td><td>强制 Hook 规则</td><td>错误</td></tr><tr><td><code>react-hooks/exhaustive-deps</code></td><td>验证依赖关系数组中的依赖</td><td>警告</td></tr></tbody></table><h2 id="vue-规则" tabindex="-1">Vue 规则 <a class="header-anchor" href="#vue-规则" aria-label="Permalink to &quot;Vue 规则&quot;">​</a></h2><p><code>smart/vue</code> 配置包含 Vue 项目的专用规则：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>vue/component-name-in-template-casing</code></td><td>强制模板中组件名称大小写</td><td>错误</td></tr><tr><td><code>vue/html-closing-bracket-newline</code></td><td>要求或禁止标签的闭括号前有一个换行</td><td>错误</td></tr><tr><td><code>vue/html-closing-bracket-spacing</code></td><td>要求或禁止标签的闭括号之前有空格</td><td>错误</td></tr><tr><td><code>vue/html-indent</code></td><td>强制一致缩进</td><td>错误</td></tr><tr><td><code>vue/html-quotes</code></td><td>强制 HTML 属性的引号样式</td><td>错误</td></tr><tr><td><code>vue/max-attributes-per-line</code></td><td>强制每行的最大属性数</td><td>警告</td></tr><tr><td><code>vue/multiline-html-element-content-newline</code></td><td>要求多行元素的内容前后有一个换行符</td><td>警告</td></tr><tr><td><code>vue/mustache-interpolation-spacing</code></td><td>强制模板插值的统一间距</td><td>错误</td></tr><tr><td><code>vue/no-multi-spaces</code></td><td>禁止多个空格</td><td>错误</td></tr><tr><td><code>vue/no-template-shadow</code></td><td>禁止在模板中声明变量并遮蔽外部作用域中声明的变量</td><td>错误</td></tr><tr><td><code>vue/no-unused-components</code></td><td>禁止使用未在模板中使用的组件</td><td>错误</td></tr><tr><td><code>vue/no-unused-vars</code></td><td>禁止模板中未使用的变量</td><td>错误</td></tr><tr><td><code>vue/order-in-components</code></td><td>强制组件中的属性顺序</td><td>警告</td></tr></tbody></table><h2 id="nestjs-规则" tabindex="-1">NestJS 规则 <a class="header-anchor" href="#nestjs-规则" aria-label="Permalink to &quot;NestJS 规则&quot;">​</a></h2><p><code>smart/nestjs</code> 配置针对 NestJS 后端项目：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th><th>严重级别</th></tr></thead><tbody><tr><td><code>@typescript-eslint/explicit-member-accessibility</code></td><td>要求类成员的显式可访问性修饰符</td><td>错误</td></tr><tr><td><code>@typescript-eslint/no-useless-constructor</code></td><td>禁止不必要的构造函数</td><td>错误</td></tr><tr><td><code>@typescript-eslint/explicit-function-return-type</code></td><td>要求函数和类方法的显式返回类型</td><td>错误</td></tr><tr><td><code>@typescript-eslint/ban-types</code></td><td>禁止使用特定类型</td><td>错误</td></tr><tr><td><code>@typescript-eslint/no-var-requires</code></td><td>禁止使用 var 关键字</td><td>错误</td></tr><tr><td><code>@typescript-eslint/interface-name-prefix</code></td><td>接口名称不应以 &quot;I&quot; 前缀命名</td><td>警告</td></tr></tbody></table><h2 id="规则定制" tabindex="-1">规则定制 <a class="header-anchor" href="#规则定制" aria-label="Permalink to &quot;规则定制&quot;">​</a></h2><p>所有规则都可以根据项目需求进行定制。请参考<a href="./配置指南">配置指南</a>了解如何覆盖或扩展默认规则配置。</p>',27)]))}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
